) {
    let Some(ix) = self.selection else { return };

    match self.contents.entries.get(ix) {
        Some(ListEntry::ProjectHeader { key, .. }) => {
            let key = key.clone();
            if !self.is_group_collapsed(&key, cx) {
                self.set_group_expanded(&key, false, cx);
                self.update_entries(cx);
